<?php
require 'config/database.php';require 'includes/functions.php';$id=(int)($_GET['id']??0);$p=['name'=>'','sku'=>'','category'=>'','description'=>'','unit_cost'=>'0.00','quantity'=>0,'reorder_level'=>5];$errors=[];
if($id){$s=$pdo->prepare("SELECT * FROM products WHERE id=? AND is_archived=0");$s->execute([$id]);$found=$s->fetch();if(!$found){flash('error','Product not found.');header('Location: products.php');exit;}$p=$found;}
$title=$id?'Edit product':'Add product';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['name','sku','category','description','unit_cost','quantity','reorder_level'] as $k)$p[$k]=trim((string)($_POST[$k]??''));$p['sku']=strtoupper($p['sku']);if($p['name']==='')$errors[]='Product name is required.';if($p['sku']==='')$errors[]='SKU is required.';if(!is_numeric($p['unit_cost'])||$p['unit_cost']<0)$errors[]='Unit cost must be a non-negative number.';foreach(['quantity','reorder_level'] as $k)if(filter_var($p[$k],FILTER_VALIDATE_INT)===false||$p[$k]<0)$errors[]='Quantity and reorder level must be non-negative whole numbers.';$s=$pdo->prepare("SELECT id FROM products WHERE sku=? AND id<>?");$s->execute([$p['sku'],$id]);if($s->fetch())$errors[]='SKU must be unique.';
if(!$errors){if($id){$s=$pdo->prepare("UPDATE products SET name=?,sku=?,category=?,description=?,unit_cost=?,quantity=?,reorder_level=? WHERE id=?");$s->execute([$p['name'],$p['sku'],$p['category'],$p['description'],$p['unit_cost'],$p['quantity'],$p['reorder_level'],$id]);flash('success','Product updated successfully.');}else{$s=$pdo->prepare("INSERT INTO products(name,sku,category,description,unit_cost,quantity,reorder_level) VALUES(?,?,?,?,?,?,?)");$s->execute([$p['name'],$p['sku'],$p['category'],$p['description'],$p['unit_cost'],$p['quantity'],$p['reorder_level']]);flash('success','Product added to inventory.');}header('Location: products.php');exit;}}
require 'includes/header.php';?>
<section class="heading"><div><small>CATALOG / PRODUCT DETAILS</small><h1><?=$id?'Edit product':'Add a product'?></h1><p>Enter product information and stock thresholds.</p></div><a class="btn secondary" href="products.php">← Back to products</a></section><section class="panel form-panel"><?php if($errors):?><div class="alert error"><ul><?php foreach($errors as $err):?><li><?=e($err)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><h2>Product information</h2><p class="muted">Fields marked * are required.</p><div class="form-grid"><label>Product name *<input name="name" required maxlength="150" value="<?=e($p['name'])?>" placeholder="Wireless Keyboard"></label><label>SKU / Product code *<input name="sku" required maxlength="60" value="<?=e($p['sku'])?>" placeholder="ACC-001"></label><label>Category<input name="category" maxlength="100" value="<?=e($p['category'])?>" placeholder="Accessories"></label><label>Unit cost (₦) *<input type="number" name="unit_cost" min="0" step=".01" required value="<?=e($p['unit_cost'])?>"></label><label>Current quantity *<input type="number" name="quantity" min="0" step="1" required value="<?=e($p['quantity'])?>"></label><label>Reorder level *<input type="number" name="reorder_level" min="0" step="1" required value="<?=e($p['reorder_level'])?>"><small>Low-stock alerts appear at this quantity.</small></label><label class="full">Description<textarea name="description" rows="4" maxlength="1000"><?=e($p['description'])?></textarea></label></div><div class="form-actions"><a class="btn secondary" href="products.php">Cancel</a><button class="btn primary"><?=$id?'Save changes':'Create product'?> →</button></div></form></section><?php require 'includes/footer.php';?>